import {SCENARIOS,PLAYERS,position} from './engine.js';
import {playEvidence} from './play-evidence.js';
const $=id=>document.getElementById(id),scenario=SCENARIOS.find(s=>s.id==='wide');
let step=0,corrected=false,timer=null,paused=matchMedia('(prefers-reduced-motion: reduce)').matches||!!navigator.connection?.saveData;
const film=$('atmosphere');
const stories=[['scout','SCOUT / THE OBSERVATION','Follow the movement.','The ball isn’t the whole story.','Watch the winger and the defender move toward the same side. Timing is visible. Intent is not.'],['guide','GUIDE / THE EXPLANATION','A way into the game.','A run can change the space.','An off-ball run is movement without the ball. It can offer a teammate another route. These records don’t prove why the defender moved.'],['check','CHECK / THE CHALLENGE','Put the explanation to the test.','What if the evidence changes?','The original record shows the defender moving sideways. Apply corrected tracking and see which part of the story must change.']];
function draw(){const ns='http://www.w3.org/2000/svg',create=(tag,attrs)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);return n;};$('players').replaceChildren();$('trails').replaceChildren();for(const p of PLAYERS){const xy=position(scenario,p.id,16,corrected);$('players').append(create('circle',{cx:xy[0],cy:xy[1],r:[7,102].includes(p.id)?1.6:.8,fill:p.id<100?'#e5e999':'#87d9ef',opacity:[7,102].includes(p.id)?1:.3}));}for(const id of[7,102]){const start=position(scenario,id,0,corrected),end=position(scenario,id,16,corrected),color=id===7?'#e5e999':'#87d9ef';$('trails').append(create('path',{d:`M${start.join(' ')} L${end.join(' ')}`,stroke:color,'stroke-width':.6,fill:'none',class:'trail'}),create('circle',{cx:end[0],cy:end[1],r:2.4,stroke:color,'stroke-width':.25,fill:'none'}));const label=create('text',{x:end[0]+3,y:end[1]+1,fill:color,'font-size':2.3,'font-family':'Arial'});label.textContent=id===7?'MOREAU':'LAURENT';$('trails').append(label);}}
function render(){const s=stories[step],m=playEvidence({scenario:'wide',time:16,corrected,tracking:true,language:'en'});$('portrait').src=`assets/${s[0]}-portrait.webp`;$('role').textContent=s[1];$('state').textContent=corrected?'The source changed. So did the claim.':s[2];$('headline').textContent=corrected?'The story follows the evidence.':s[3];$('explanation').textContent=corrected?m.movement:s[4];$('withdrawn').hidden=!corrected;$('withdrawn').textContent='Withdraw the movement claim. Keep the completed passes. Neither record establishes the cause of the defender’s decision.';$('change').hidden=step!==2;$('change').firstChild.textContent=corrected?'Restore original evidence ':'Change the evidence ';$('revision').textContent=corrected?'CORRECTED RECORD':'ORIGINAL RECORD';$('receipt').textContent=corrected?'SYNTHETIC TRACKING / CORRECTED':'SYNTHETIC TRACKING / ORIGINAL';$('round').textContent=`0${step+1} / 03`;document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.step===step)));draw();}
function stop(){clearTimeout(timer);timer=null;}
function schedule(){stop();if(!paused&&!document.hidden&&step<2)timer=setTimeout(()=>{step++;render();schedule();},6500);}
function motion(){document.body.classList.toggle('paused',paused);$('motion').textContent=paused?'Play motion':'Pause motion';$('motion').setAttribute('aria-pressed',String(paused));if(paused||document.hidden)film.pause();else{if(!film.getAttribute('src'))film.src='assets/pitchside-clean-scene-0.mp4';film.play().catch(()=>{});}schedule();}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{stop();step=+b.dataset.step;corrected=false;render();}));
$('change').addEventListener('click',()=>{stop();corrected=!corrected;render();});$('motion').addEventListener('click',()=>{paused=!paused;motion();});
document.addEventListener('visibilitychange',motion);window.addEventListener('pagehide',()=>{stop();film.pause();});render();motion();
